1: /**
2:  * Translate child Engine StreamEvents into ChatEntry-shaped objects so the
3:  * AgentDock detail view (which reuses App.renderEntry) can show a sub-agent's
4:  * conversation in the same visual language as the main feed.
5:  *
6:  * The transcript is the canonical record for one background sub-agent. State
7:  * (current thinking entry, currently-streaming assistant_text, in-flight
8:  * tool_start map) lives in a per-agent translator. Each translator instance
9:  * appends ChatEntry-shaped objects via `append` and mutates them via `update`,
10:  * mirroring how App.tsx's handleStreamEvent talks to chatStore but isolated to
11:  * a single agent's transcript.
12:  *
13:  * The output shapes intentionally match `src/ui/store.ts#ChatEntryData` so the
14:  * existing renderEntry switch picks them up without code changes.
15:  */
16: import type { StreamEvent } from "../../types.js";
17: import { asyncAgentRegistry, type AgentTranscriptEntry } from "./agent-registry.js";
18: 
19: interface TranslatedEntry {
20:   id: string;
21:   type: string;
22:   [key: string]: unknown;
23: }
24: 
25: let entryIdCounter = 0;
26: function nextId(agentId: string): string {
27:   return `bg-${agentId}-${++entryIdCounter}`;
28: }
29: 
30: /**
31:  * Create a transcript translator scoped to one background sub-agent. Returned
32:  * function is a StreamCallback drop-in: feed it the child Engine's events and
33:  * it maintains the agent's transcript in `asyncAgentRegistry`.
34:  */
35: export function createTranscriptTranslator(agentId: string): (event: StreamEvent) => void {
36:   // Local state for THIS agent. Background sub-agents run independently so
37:   // each gets its own translator; no cross-agent state.
38:   let streamingAssistantId: string | undefined;
39:   let thinkingId: string | undefined;
40:   // toolCallId → tool_start entry id. Lets tool_use_args_delta find the right
41:   // tool_start to patch.
42:   const toolStartByCallId = new Map<string, string>();
43: 
44:   function patchEntry(
45:     entryId: string,
46:     patch: (e: AgentTranscriptEntry) => AgentTranscriptEntry,
47:   ): void {
48:     const a = asyncAgentRegistry.get(agentId);
49:     if (!a?.transcript) return;
50:     const idx = a.transcript.findIndex((e) => e.id === entryId);
51:     if (idx < 0) return;
52:     a.transcript[idx] = patch(a.transcript[idx]!);
53:     asyncAgentRegistry.touchTranscript(agentId);
54:   }
55: 
56:   function dropEntry(entryId: string): void {
57:     const a = asyncAgentRegistry.get(agentId);
58:     if (!a?.transcript) return;
59:     a.transcript = a.transcript.filter((e) => e.id !== entryId);
60:     asyncAgentRegistry.touchTranscript(agentId);
61:   }
62: 
63:   function append(data: Omit<TranslatedEntry, "id">): string {
64:     const id = nextId(agentId);
65:     asyncAgentRegistry.appendToTranscript(agentId, {
66:       ...data,
67:       id,
68:     } as AgentTranscriptEntry);
69:     return id;
70:   }
71: 
72:   return (event: StreamEvent) => {
73:     switch (event.type) {
74:       // ── thinking ─────────────────────────────────────────────────
75:       case "stream_request_start": {
76:         if (thinkingId) {
77:           dropEntry(thinkingId);
78:           thinkingId = undefined;
79:         }
80:         thinkingId = append({ type: "thinking", agentId });
81:         break;
82:       }
83: 
84:       case "thinking_delta": {
85:         // Sub-agent thinking content is collapsed in the dock view — we
86:         // don't replicate the verb spinner. Keep the empty thinking
87:         // placeholder; renderEntry shows it as a spinner row.
88:         break;
89:       }
90: 
91:       // ── assistant text (streaming) ───────────────────────────────
92:       case "text_delta": {
93:         if (thinkingId) {
94:           dropEntry(thinkingId);
95:           thinkingId = undefined;
96:         }
97:         if (streamingAssistantId) {
98:           patchEntry(streamingAssistantId, (e) => ({
99:             ...e,
100:             text: String(e.text ?? "") + (event as any).text,
101:           }));
102:         } else {
103:           streamingAssistantId = append({
104:             type: "assistant_text",
105:             text: (event as any).text,
106:             streaming: true,
107:             agentId,
108:           });
109:         }
110:         break;
111:       }
112: 
113:       // ── tool call ────────────────────────────────────────────────
114:       case "tool_use_start": {
115:         if (streamingAssistantId) {
116:           patchEntry(streamingAssistantId, (e) => ({ ...e, streaming: false }));
117:           streamingAssistantId = undefined;
118:         }
119:         if (thinkingId) {
120:           dropEntry(thinkingId);
121:           thinkingId = undefined;
122:         }
123:         const tc = (event as any).toolCall;
124:         const startId = append({
125:           type: "tool_start",
126:           toolName: tc.toolName,
127:           args: tc.args,
128:           toolCallId: tc.id,
129:           agentId,
130:         });
131:         if (tc.id) toolStartByCallId.set(tc.id, startId);
132:         append({ type: "tool_running", toolName: tc.toolName, agentId });
133:         break;
134:       }
135: 
136:       case "tool_use_args_delta": {
137:         const ev = event as any;
138:         const startId = toolStartByCallId.get(ev.toolCallId);
139:         if (!startId) break;
140:         patchEntry(startId, (e) => ({ ...e, args: ev.args }));
141:         break;
142:       }
143: 
144:       case "tool_result": {
145:         const r = (event as any).result;
146:         const a = asyncAgentRegistry.get(agentId);
147:         if (a?.transcript) {
148:           a.transcript = a.transcript.filter(
149:             (e) => !(e.type === "tool_running" && (e as any).toolName === r.toolName),
150:           );
151:           asyncAgentRegistry.touchTranscript(agentId);
152:         }
153:         append({
154:           type: "tool_result",
155:           toolName: r.toolName,
156:           result: r.result,
157:           error: r.error,
158:           agentId,
159:         });
160:         break;
161:       }
162: 
163:       // ── lifecycle: finalize streaming on turn end ───────────────
164:       case "turn_complete":
165:       case "tombstone": {
166:         if (streamingAssistantId) {
167:           patchEntry(streamingAssistantId, (e) => ({ ...e, streaming: false }));
168:           streamingAssistantId = undefined;
169:         }
170:         if (thinkingId) {
171:           dropEntry(thinkingId);
172:           thinkingId = undefined;
173:         }
174:         break;
175:       }
176: 
177:       // ── errors surface as a card in the transcript ──────────────
178:       case "error": {
179:         if (thinkingId) {
180:           dropEntry(thinkingId);
181:           thinkingId = undefined;
182:         }
183:         append({
184:           type: "error",
185:           error: (event as any).error,
186:           agentId,
187:         });
188:         break;
189:       }
190: 
191:       default:
192:         break;
193:     }
194:   };
195: }

