2216:       const emit = (event: StreamEvent) => {
2217:         if (!this.config.signal?.aborted) this.config.onStream?.(event);
2218:       };
2219:       emit({
2220:         type: "stream_request_start",
2221:         turnNumber: this.turnCount,
2222:         messageId: assistantMessageId,
2223:       });
2224:       if (response.reasoningContent) {
2225:         emit({ type: "thinking_delta", text: response.reasoningContent });
2226:       }
2227:       if (response.text) emit({ type: "text_delta", text: response.text });
2228:       return response;
